/**
 * Report logos, embedded as base64 because production runs on Cloudflare
 * Workers, which has no filesystem: the bytes cannot be read from `public/` at
 * request time. The same PNGs live in `public/brand/report/` for HTML.
 *
 * Layout follows the End of Term Report template: the Kagawaran ng Edukasyon
 * seal centred at the top of the sheet, and DepEd, Bagong Pilipinas and the
 * Division of Sarangani along the bottom, in that order. Sources are 2-3x the
 * drawn size so they stay crisp in print. Server-only in practice (~100 KB).
 */

export type ReportLogo = {
  key: string;
  alt: string;
  /** Public path of the same image, for HTML. */
  src: string;
  width: number;
  height: number;
  base64: string;
};

export const REPORT_TOP_LOGO: ReportLogo =
{
  key: "DEPED_SEAL",
  alt: "Kagawaran ng Edukasyon seal",
  src: "/brand/report/deped-seal.png",
  width: 300,
  height: 300,
  base64:
    "",
};

